import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { ContentService, PortfolioData } from '../../services/content.service';

@Component({
  selector: 'app-contact',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="contact-container" *ngIf="content">
      <div class="page-header">
        <div>
          <h1 class="page-title">Get In Touch with Amit</h1>
          <p class="page-subtitle">Send a direct message or recruiter inquiry. Saved directly to SQL Server Database.</p>
        </div>
      </div>

      <div class="contact-grid">
        <!-- Contact Details Card -->
        <div class="card contact-info-card">
          <h3 style="font-size: 1.2rem; font-weight: 800; color: #ffffff;">Contact Information</h3>

          <div class="contact-method">
            <a [href]="'mailto:' + content.personalInfo.email" class="contact-icon-box clickable-icon" title="Send Email">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#818cf8" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <rect x="2" y="4" width="20" height="16" rx="2"></rect>
                <path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7"></path>
              </svg>
            </a>
            <div>
              <div class="spec-label">EMAIL ADDRESS</div>
              <a [href]="'mailto:' + content.personalInfo.email" class="spec-val contact-link" title="Click to send email">
                {{ content.personalInfo.email }}
              </a>
            </div>
          </div>

          <div class="contact-method">
            <a [href]="'tel:' + content.personalInfo.phone.replace(' ', '')" class="contact-icon-box clickable-icon" title="Call or Message">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#38bdf8" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"></path>
              </svg>
            </a>
            <div>
              <div class="spec-label">PHONE NUMBER</div>
              <a [href]="'tel:' + content.personalInfo.phone.replace(' ', '')" class="spec-val contact-link" title="Click to call or message">
                {{ content.personalInfo.phone }}
              </a>
            </div>
          </div>

          <div class="contact-method">
            <div class="contact-icon-box">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#f43f5e" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0z"></path>
                <circle cx="12" cy="10" r="3"></circle>
              </svg>
            </div>
            <div>
              <div class="spec-label">CURRENT LOCATION</div>
              <div class="spec-val">{{ content.personalInfo.location }}</div>
            </div>
          </div>

          <div style="border-top: 1px solid #334155; padding-top: 20px; margin-top: 10px;">
            <h4 style="font-size: 0.9rem; font-weight: 700; color: #818cf8; margin-bottom: 12px;">Social & Developer Profiles</h4>
            <div style="display: flex; gap: 10px;">
              <a [href]="content.personalInfo?.github || 'https://github.com/amiitmaurya'" target="_blank" rel="noopener noreferrer" class="btn btn-secondary" style="padding: 8px 14px; font-size: 0.825rem;">
                GitHub ↗
              </a>
              <a [href]="content.personalInfo?.linkedin || 'https://linkedin.com/in/amit-mauryaa'" target="_blank" rel="noopener noreferrer" class="btn btn-secondary" style="padding: 8px 14px; font-size: 0.825rem;">
                LinkedIn ↗
              </a>
            </div>
          </div>
        </div>

        <!-- Contact Form -->
        <div class="card">
          <h3 style="font-size: 1.2rem; font-weight: 800; color: #ffffff; margin-bottom: 20px;">Send a Direct Message</h3>

          <div *ngIf="submitted" style="background: rgba(16, 185, 129, 0.2); border: 1px solid #10b981; color: #34d399; padding: 16px; border-radius: 10px; margin-bottom: 20px; font-weight: 600; display: flex; align-items: center; gap: 10px;">
            ✅ Thank you! Your message has been sent and saved to SQL Server database.
          </div>

          <form (ngSubmit)="handleSubmit()" #contactForm="ngForm">
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
              <div class="form-group">
                <label>Your Name *</label>
                <input type="text" class="form-control" name="name" [(ngModel)]="formData.name" required placeholder="John Doe">
              </div>
              <div class="form-group">
                <label>Your Email *</label>
                <input type="email" class="form-control" name="email" [(ngModel)]="formData.email" required placeholder="john@example.com">
              </div>
            </div>

            <div class="form-group">
              <label>Subject</label>
              <input type="text" class="form-control" name="subject" [(ngModel)]="formData.subject" placeholder="Project Inquiry / Job Opportunity">
            </div>

            <div class="form-group">
              <label>Message Body *</label>
              <textarea class="form-control" rows="5" name="message" [(ngModel)]="formData.message" required placeholder="Type your message here..."></textarea>
            </div>

            <button type="submit" class="btn btn-primary" [disabled]="sending || !contactForm.form.valid">
              {{ sending ? 'Sending Message...' : 'Send Message ➔' }}
            </button>
          </form>
        </div>
      </div>
    </div>
  `
})
export class ContactComponent implements OnInit {
  content!: PortfolioData;
  formData = {
    name: '',
    email: '',
    subject: '',
    message: ''
  };
  sending: boolean = false;
  submitted: boolean = false;

  constructor(
    private contentService: ContentService,
    private http: HttpClient
  ) {}

  ngOnInit(): void {
    this.contentService.content$.subscribe(data => {
      this.content = data;
    });
  }

  async handleSubmit(): Promise<void> {
    if (!this.formData.name || !this.formData.email || !this.formData.message) return;

    this.sending = true;
    const msgObj = {
      id: Date.now().toString(),
      name: this.formData.name,
      email: this.formData.email,
      subject: this.formData.subject || 'Inquiry',
      message: this.formData.message,
      createdAt: new Date().toISOString()
    };

    try {
      await firstValueFrom(this.http.post('http://localhost:5000/api/messages', msgObj));
    } catch (err) {
      console.warn('API message save fallback to localStorage');
      const stored = JSON.parse(localStorage.getItem('contact_messages') || '[]');
      stored.unshift(msgObj);
      localStorage.setItem('contact_messages', JSON.stringify(stored));
    }

    this.sending = false;
    this.submitted = true;
    this.formData = { name: '', email: '', subject: '', message: '' };

    setTimeout(() => {
      this.submitted = false;
    }, 5000);
  }
}
